<?php
$id=(int)($_GET['id']??0);$q=$pdo->prepare('SELECT * FROM products WHERE id=?');$q->execute([$id]);$p=$q->fetch();if(!$p){echo '<div class="alert danger">Product not found.</div>';return;}$s=stock_row($id);
echo '<div class="page-head"><div><a class="back" href="?page=stocks">← Current Stocks</a><h1>'.e($p['name']).'</h1><p>'.e($p['master_sku'].' · '.inventory_filter_brand($p['brand']).' · '.$p['category']).'</p></div></div><div class="mini-kpis">';foreach(['Beginning'=>$s['beginning'],'Sellable Stock'=>$s['current'],'Reserved for Orders'=>$s['reserved'],'Available to Sell'=>$s['available'],'Non-Sellable Stock'=>$s['nonsellable'],'Total Physical Stock'=>$s['physical']] as $k=>$v)echo '<div><span>'.e($k).'</span><strong>'.$v.'</strong></div>';echo '</div><div class="card"><h3>Current Platform Allocation</h3><div class="control-list">';foreach(['Lazada','Shopee','TikTok'] as $pl)echo '<div><span>'.$pl.'</span><b>'.platform_qty($pl,$id).'</b></div>';echo '</div></div>';platform_alignment_card($id);usability_terms();
if(!adjustments_ready()){echo '<div class="alert warn">Run upgrade_adjustments_reports.php to enable dated movement reports.</div>';return;}
try{$input=$_GET;$input['report']='movement';$input['product_id']=$id;$f=report_filters($input);echo '<div class="card"><h3>Movement History Filters</h3><form method="get" class="report-filter-grid"><input type="hidden" name="page" value="product_detail"><input type="hidden" name="id" value="'.$id.'"><label>From Date<input type="date" name="from" value="'.e($f['from']).'" required></label><label>To Date<input type="date" name="to" value="'.e($f['to']).'" max="'.date('Y-m-d').'" required></label><label>Movement Type<select name="movement"><option value="">All Movements</option>';foreach(['Beginning Balance','Inflow','Outflow','Inventory Count Adjustment','Restricted','Platform Transfer','Platform Redistribution','Reversal'] as $v)echo '<option '.($f['movement']===$v?'selected':'').'>'.e($v).'</option>';echo '</select></label><label>Platform<select name="platform"><option value="">All Platforms / Main Inventory</option>';foreach(['Shopee','Lazada','TikTok'] as $pl)echo '<option '.($f['platform']===$pl?'selected':'').'>'.$pl.'</option>';echo '</select></label><label>Search Reference<input name="reference" value="'.e($_GET['reference']??'').'" placeholder="Order ID / receipt / count reference"></label><div class="modal-actions"><button class="btn secondary">Apply Filters</button><a class="btn ghost" href="?page=product_detail&id='.$id.'">Clear Filters</a></div></form></div>';$r=inventory_report_build($input);report_render_result($r,'product_detail');if(om_ready())om_product_activity($id,$f);}catch(Throwable $ex){echo '<div class="alert danger">'.e(safe_error_message($ex)).'</div>';}
